text:
{
  "title_novice": "ВНК — не резкая граница",
  "summary": [
    {"text": "В водоплавающей залежи нефть занимает только верхнюю часть коллектора, а граница с водой размыта.", "claims": ["c1", "c3"]},
    {"text": "Между нефтью и водой лежит переходная зона: её верх — подошва зоны предельного нефтенасыщения, низ — зеркало воды.", "claims": ["c7", "c8", "c9", "c10"]},
    {"text": "Мощность переходной зоны меняется от долей метра до 20–30 м, поэтому ВНК нельзя считать резкой линией.", "claims": ["c11", "c12"]}
  ],
  "claims": [
    {"key": "c1", "text": "В водоплавающей залежи нефть или газ занимают только верхнюю часть коллектора.", "kind": "observation", "unit_id": "u-026-6279d5", "page": 26, "quote": "При насыщении коллектора нефтью или газом только в верхней части, что наблюдается в водоплавающих нефтяных залежах", "numbers": [], "question": null},
    {"key": "c2", "text": "Положение ВНК по данным метода сопротивлений определяют в таких залежах.", "kind": "observation", "unit_id": "u-026-6279d5", "page": 26, "quote": "по данным метода сопротивлений определяют положение водонефтяного контакта (ВНК)", "numbers": [], "question": null},
    {"key": "c3", "text": "Для таких коллекторов переход от нефти к воде постепенный, а не резкий.", "kind": "observation", "unit_id": "u-026-6279d5", "page": 26, "quote": "нефтеносных или газоводяного коллектора постепенный", "numbers": [], "question": null},
    {"key": "c4", "text": "Постепенность перехода объясняется капиллярными силами: они влияют на распределение воды в нижней части нефтяной зоны.", "kind": "inference", "unit_id": "u-026-6279d5", "page": 26, "quote": "Это объясняется влиянием капиллярных сил на распределение воды в порах нижней части нефтенасыщенного коллектора", "numbers": [], "question": null},
    {"key": "c5", "text": "В зоне максимального нефтенасыщения удельное сопротивление ρп максимально, а коэффициент водонасыщения Кв минимален.", "kind": "observation", "unit_id": "u-026-6279d5", "page": 26, "quote": "наличие зоны максимального нефтенасыщения (максимальные значения ρп и Кп, минимальные - Кв)", "numbers": [], "question": "q1"},
    {"key": "c6", "text": "Для водной части коллектора (без нефти) принимают Кн = 0 и Кв = 1; по тексту значения меняются от нефтяной части к этой.", "kind": "observation", "unit_id": "u-026-e4079b", "page": 26, "quote": "этих параметров в нефтеносной части для коллектора, для которой ρп = ρкп, Кп = 0, Кв = 1", "numbers": ["0", "1"], "question": "q1"},
    {"key": "c7", "text": "Легенда рисунка: зона предельного нефтенасыщения (1) и переходная зона — зона недонасыщения (2).", "kind": "observation", "unit_id": "u-027-20f5c5", "page": 27, "quote": "1 – зона предельного нефтенасыщения; 2 – зона недонасыщения (переходная)", "numbers": [], "question": null},
    {"key": "c8", "text": "Верхняя и нижняя границы переходной зоны на рисунке: I — верхняя, II — нижняя, зеркало воды.", "kind": "observation", "unit_id": "u-027-20f5c5", "page": 27, "quote": "I, II – верхняя и нижняя (зеркало воды) границы переходной зоны", "numbers": [], "question": null},
    {"key": "c9", "text": "Верхняя граница переходной зоны — подошва зоны предельного нефтенасыщения.", "kind": "observation", "unit_id": "u-027-3cf341", "page": 27, "quote": "Границами переходной зоны являются: вверху – подош", "numbers": [], "question": null},
    {"key": "c10", "text": "Нижняя граница переходной зоны — зеркало воды, кровля водоносной части коллектора.", "kind": "observation", "unit_id": "u-027-3cf341", "page": 27, "quote": "зеркало воды, т. е. кровля водоносной части", "numbers": [], "question": null},
    {"key": "c11", "text": "Мощность переходной зоны от долей метра для чистых кварцевых терригенных коллекторов с высокой проницаемостью.", "kind": "observation", "unit_id": "u-027-89e593", "page": 27, "quote": "Мощность переходной зоны изменяется от долей метра для чистых кварцевых терригенных коллекторов с высокой проницаемостью", "numbers": [], "question": null},
    {"key": "c12", "text": "Для глинистых полимиктовых коллекторов (Западная Сибирь) мощность переходной зоны до 20–30 м.", "kind": "observation", "unit_id": "u-027-89e593", "page": 27, "quote": "до 20-30 м для глинистых полимиктовых коллекторов (Западная Сибирь)", "numbers": ["20", "30"], "question": null},
    {"key": "c13", "text": "Расстояние между зеркалом воды и ВНК колеблется от долей метра до 5 м и более.", "kind": "observation", "unit_id": "u-027-89e593", "page": 27, "quote": "расстояние между зеркалом воды и ВНК колеблется от долей метра до 5 м и более", "numbers": ["5"], "question": null}
  ],
  "mechanism": [
    {"text": "В водоплавающей залежи нефть или газ занимают только верхнюю часть коллектора; ниже лежит вода.", "claims": ["c1"], "hypothesis": false},
    {"text": "Капиллярные силы распределяют воду в порах нижней части нефтяной зоны и удерживают её там.", "claims": ["c4"], "hypothesis": false},
    {"text": "Поэтому переход от нефти к воде идёт постепенно, через переходную зону, а не одной резкой поверхностью.", "claims": ["c3", "c4"], "hypothesis": false},
    {"text": "Сверху вниз: зона предельного нефтенасыщения, затем переходная зона, затем водоносный коллектор.", "claims": ["c7"], "hypothesis": false},
    {"text": "В зоне предельного нефтенасыщения ρп максимально, Кв минимально; в водной части Кн = 0, Кв = 1.", "claims": ["c5", "c6"], "hypothesis": false},
    {"text": "По разрезу переходной зоны значения ρп, Кн и Кв меняются от нефтяных значений к водным.", "claims": ["c5", "c6"], "hypothesis": false},
    {"text": "Нефть плохо проводит электрический ток, а пластовая вода проводит, поэтому сопротивление растёт с нефтенасыщением.", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "Специалист делит разрез на три части: зона предельного нефтенасыщения, переходная зона и водоносный коллектор.", "claims": ["c7", "c8"]},
    {"text": "Положение ВНК по данным метода сопротивлений определяют отдельно, как отдельную задачу интерпретации.", "claims": ["c2"]},
    {"text": "Границы переходной зоны ищут по кривой сопротивления, опираясь на её верхнюю и нижнюю границы.", "claims": ["c9", "c10"], "hypothesis": true},
    {"text": "Мощность переходной зоны ожидают по типу коллектора: чистый кварцевый или глинистый полимиктовый.", "claims": ["c11", "c12"]}
  ],
  "nuances": [
    {"text": "В чистых кварцевых коллекторах с высокой проницаемостью переходная зона тонкая: от долей метра.", "claims": ["c11"]},
    {"text": "В глинистых полимиктовых коллекторах Западной Сибири переходная зона достигает 20–30 м.", "claims": ["c12"]},
    {"text": "Расстояние между зеркалом воды и ВНК колеблется от долей метра до 5 м и более.", "claims": ["c13"]},
    {"text": "Так как переход постепенный, точная отметка ВНК зависит от выбранного критерия.", "claims": ["c3"], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Почему переходная зона тонкая в чистом песке", "text": "Гипотеза: толщину зоны задают размер пор и капиллярное давление. В главе прямо об этом не сказано.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Мощность переходной зоны: от долей метра (чистые кварцевые коллекторы с высокой проницаемостью) до 20–30 м (глинистые полимиктовые, Западная Сибирь).", "claims": ["c11", "c12"]},
    {"text": "Расстояние между зеркалом воды и ВНК: от долей метра до 5 м и более.", "claims": ["c13"]},
    {"text": "Водная часть коллектора: Кн = 0 и Кв = 1.", "claims": ["c6"]},
    {"text": "Зона максимального нефтенасыщения: максимум ρп, минимум Кв.", "claims": ["c5"]}
  ],
  "terms_defined": [
    {"term": "переходная зона", "term_en": "transition zone", "abbr": "", "definition": "Зона между нефтяной частью коллектора и водоносной частью, где нефти меньше, чем в зоне предельного нефтенасыщения.", "claims": ["c7", "c9"]},
    {"term": "зеркало воды", "term_en": "water level (lower boundary of transition zone)", "abbr": "", "definition": "Нижняя граница переходной зоны; это кровля водоносной части коллектора.", "claims": ["c10", "c8"]},
    {"term": "зона предельного нефтенасыщения", "term_en": "zone of maximum oil saturation", "abbr": "", "definition": "Верхняя часть нефтяного коллектора с максимальным нефтенасыщением; её подошва — верхняя граница переходной зоны.", "claims": ["c5", "c9"]},
    {"term": "капиллярные силы", "term_en": "capillary forces", "abbr": "", "definition": "Силы в тонких порах породы, которые удерживают жидкость и влияют на распределение воды и нефти.", "claims": ["c4"]},
    {"term": "водоплавающая залежь", "term_en": "water-bottom oil deposit", "abbr": "", "definition": "Нефтяная залежь, под которой лежит вода; нефть или газ занимают в ней верхнюю часть коллектора.", "claims": ["c1"]},
    {"term": "газоводяной контакт", "term_en": "gas-water contact", "abbr": "ГВК", "definition": "Граница между газом сверху и водой снизу; по смыслу аналог ВНК для газа.", "claims": []}
  ],
